UPDATE MBW_BOOTSTRAP_APPROVAL
   SET STATUS = 'CLAIMED', OPERATION_ID = :operationId, CLAIM_OWNER_ID = :claimOwnerId,
       CLAIMED_AT = (CURRENT_TIMESTAMP(6) AT TIME ZONE 'UTC'), CLAIM_EXPIRES_AT = (CURRENT_TIMESTAMP(6) AT TIME ZONE 'UTC') + (:leaseDurationMicros * INTERVAL '1 microsecond'),
       UPDATED_AT = (CURRENT_TIMESTAMP(6) AT TIME ZONE 'UTC')
 WHERE TOKEN_HASH = :tokenHash
   AND ENV_FINGERPRINT = :environmentFingerprint
   AND EXPIRES_AT > (CURRENT_TIMESTAMP(6) AT TIME ZONE 'UTC')
   AND (
        STATUS = 'APPROVED'
        OR (STATUS = 'CLAIMED' AND OPERATION_ID = :operationId AND CLAIM_EXPIRES_AT <= (CURRENT_TIMESTAMP(6) AT TIME ZONE 'UTC'))
   )
